package com.onlymymoney.adapter.out.persistence;

import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * JPA entity mapped to the {@code accounts} table.
 * <p>
 * It is the persistence representation of an account; the domain model is
 * {@code com.onlymymoney.domain.model.Account}, and the adapter is responsible for converting between them.
 */
@Entity
@Table(name = "accounts")
public class AccountJpa {
    /** Primary key, generated by the database (identity column). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    Long id;
    /** Name of the account holder. */
    String holder;
    /** Total balance of the account, stored with precision 19 and scale 2. */
    @Column(name = "total_balance", precision = 19, scale = 2)
    BigDecimal totalBalance;
    /** Moment of the last modification of the account. */
    @Column(name = "last_modification")
    Instant lastModification;

    /**
     * Default constructor required by JPA.
     */
    public AccountJpa() {
    }

    /**
     * Creates an entity with all its fields.
     *
     * @param id the identifier ({@code null} for a new account)
     * @param h  the account holder
     * @param b  the total balance
     * @param l  the last modification timestamp
     */
    public AccountJpa(Long id, String h, BigDecimal b, Instant l) {
        this.id = id;
        holder = h;
        totalBalance = b;
        lastModification = l;
    }

    /** @return the account identifier */
    public Long getId() {
        return id;
    }

    /** @return the account holder */
    public String getHolder() {
        return holder;
    }

    /** @return the total balance of the account */
    public BigDecimal getTotalBalance() {
        return totalBalance;
    }

    /** @return the timestamp of the last modification */
    public Instant getLastModification() {
        return lastModification;
    }
}